def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]
    opp_defects = sum(1 for a, b in history if b == 'D')

    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n == 10:
        if opp_defects == 0:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n == 11:
        return 'C'

    if n == 12:
        if history[11][1] == 'D':
            return 'C'
        else:
            if opp_defects == 0:
                return 'D'

    if opp_defects == 0:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if opp_defects <= max(2, n * 0.2):
                return 'C'
            return 'D'
        else:
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
